importScripts('./vendor/fflate.js','./vendor/sha256.js');
const MAX_FILE=30*1024*1024, MAX_TOTAL=80*1024*1024;
const fail=()=>{throw Error('invalid')};
const safe=p=>typeof p==='string'&&p.length<180&&!p.includes('\\')&&!p.includes(':')&&!p.startsWith('/')&&!p.split('/').some(x=>!x||x==='.'||x==='..')&&/\.(json|png|jpg|jpeg|mp3|mp4|pdf|txt)$/i.test(p);
const decode=b=>JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(b));
const str=v=>typeof v==='string'&&v.length<6000;
const hash=async b=>crypto.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b))).map(x=>x.toString(16).padStart(2,'0')).join(''):sha256(b);
function mime(b,t){if(t==='image/png')return b[0]===137&&b[1]===80&&b[2]===78&&b[3]===71;if(t==='image/jpeg')return b[0]===255&&b[1]===216;if(t==='audio/mpeg')return (b[0]===73&&b[1]===68&&b[2]===51)||(b[0]===255&&(b[1]&224)===224);if(t==='video/mp4')return new TextDecoder().decode(b.slice(4,8))==='ftyp';if(t==='application/pdf')return new TextDecoder().decode(b.slice(0,5))==='%PDF-';return t==='application/json'}
self.onmessage=async({data:{file}})=>{try{if(file.size>40*1024*1024)fail();let total=0,count=0,entries=Object.create(null);let unpackError;
 const unzip=new fflate.Unzip(entry=>{if(++count>500||!safe(entry.name)||entries[entry.name]||entry.originalSize>MAX_FILE)fail();let chunks=[],size=0;entries[entry.name]=null;entry.ondata=(err,chunk,final)=>{if(err)throw err;size+=chunk.length;total+=chunk.length;if(size>MAX_FILE||total>MAX_TOTAL)fail();chunks.push(chunk);if(final){const out=new Uint8Array(size);let pos=0;for(const c of chunks){out.set(c,pos);pos+=c.length}entries[entry.name]=out;}};entry.start()});unzip.register(fflate.UnzipInflate);
 const raw=new Uint8Array(await file.arrayBuffer());for(let i=0;i<raw.length;i+=32768){unzip.push(raw.subarray(i,i+32768),i+32768>=raw.length);if(i%(32768*16)===0)self.postMessage({progress:Math.round(i/raw.length*65)})}
 if(!entries['book.json']||Object.values(entries).some(v=>!v))fail();const book=decode(entries['book.json']);
 if(book.schemaVersion!=='1.0'||book.learningLanguage!=='ar'||!/^[-a-zA-Z0-9._]{1,90}$/.test(book.bookId)||!/^\d+\.\d+\.\d+/.test(book.contentVersion)||!str(book.titleAr)||!Array.isArray(book.lessons)||!book.assets||!book.arabicTexts)fail();
 const locales={};if(!Array.isArray(book.instructionLocales)||book.instructionLocales.length>32)fail();for(const loc of book.instructionLocales){if(!['ar','en','tr','fr','es'].includes(loc.tag)||!safe(loc.path)||!entries[loc.path])fail();const content=decode(entries[loc.path]);if(!content.messages||Object.keys(content.messages).length>600||Object.values(content.messages).some(v=>!str(v)))fail();locales[loc.tag]=content}
 if(['ar','en','tr','fr','es'].some(x=>!locales[x]))fail();const referenceKeys=Object.keys(locales.en.messages);for(const loc of Object.values(locales)){if(referenceKeys.some(k=>!str(loc.messages[k])))fail()}
 const blobs=Object.create(null);let index=0;for(const [id,a] of Object.entries(book.assets)){if(!({image:['image/png','image/jpeg'],audio:['audio/mpeg'],video:['video/mp4'],trace:['application/json'],print:['application/pdf']}[a.kind]||[]).includes(a.mimeType))fail();if(!safe(a.path)||!entries[a.path]||entries[a.path].length!==a.bytes||a.bytes>MAX_FILE||!mime(entries[a.path],a.mimeType)||await hash(entries[a.path])!==a.sha256)fail();if(a.mimeType==='application/json'){const trace=decode(entries[a.path]);if(!Array.isArray(trace.strokes)||trace.strokes.length!==2)fail();const [p,d]=trace.strokes;if(!p||p.kind!=='path'||typeof p.path!=='string'||p.path.length>3000||!/^[MmLlCcQqSsTtHhVvZz0-9.,\s-]+$/.test(p.path)||!d||d.kind!=='dot'||!d.center||![d.center.x,d.center.y,d.radius].every(Number.isFinite)||d.center.x<0||d.center.x>560||d.center.y<70||d.center.y>360||d.radius<1||d.radius>30)fail();}blobs[id]=new Blob([entries[a.path]],{type:a.mimeType});self.postMessage({progress:65+Math.round(++index/Object.keys(book.assets).length*30)})}
 const ids=new Set();for(const lesson of book.lessons){if(!Array.isArray(lesson.activities)||lesson.activities.length>100)fail();for(const a of lesson.activities){if(!str(a.id)||ids.has(a.id)||!['listen-look','listen-select','trace'].includes(a.kind))fail();ids.add(a.id);for(const key of ['imageAssetId','audioAssetId','traceAssetId','videoAssetId'])if(a[key]&&!blobs[a[key]])fail();if(a.arabicTextId&&!book.arabicTexts[a.arabicTextId])fail();if(a.kind==='listen-select'&&(!Array.isArray(a.options)||a.options.length<2||a.options.length>8||!a.options.some(o=>o.id===a.correctOptionId)||a.options.some(o=>!blobs[o.imageAssetId]||!str(o.id))))fail();}}
 const all=book.lessons.flatMap(l=>l.activities);for(const kind of ['listen-look','listen-select','trace'])if(!all.some(a=>a.kind===kind))fail();for(const a of all){const asset=(key,kind)=>book.assets[a[key]]?.kind===kind;if(a.kind==='listen-look'&&(!asset('imageAssetId','image')||!asset('audioAssetId','audio')||!book.arabicTexts[a.arabicTextId]))fail();if(a.kind==='listen-select'&&(!asset('audioAssetId','audio')||new Set(a.options.map(o=>o.id)).size!==a.options.length||a.options.some(o=>book.assets[o.imageAssetId]?.kind!=='image')))fail();if(a.kind==='trace'&&(!asset('traceAssetId','trace')||!book.arabicTexts[a.arabicTextId]))fail();}if(book.explorations!==undefined){if(!Array.isArray(book.explorations)||book.explorations.length>10)fail();for(const scene of book.explorations){if(!scene||!str(scene.id)||book.assets[scene.imageAssetId]?.kind!=='image'||!Array.isArray(scene.hotspots)||scene.hotspots.length<1||scene.hotspots.length>12)fail();for(const h of scene.hotspots){if(!h||!all.some(a=>a.id===h.activityId&&a.kind==='listen-look')||!h.bounds)fail();const r=h.bounds;if(![r.x,r.y,r.width,r.height].every(Number.isFinite)||r.x<0||r.y<0||r.width<=0||r.height<=0||r.x+r.width>100||r.y+r.height>100)fail();}}}if(!ids.size||Object.values(book.arabicTexts).some(v=>!str(v.text)))fail();self.postMessage({success:true,book,blobs,locales});
 }catch(e){self.postMessage({error:'error.book',detail:String(e)})}};
